pub(crate) enum HintTape {
    Quartets,
    Positions,
}

struct Tape {
    words: Vec<u64>,
    used: usize,
}
impl Tape {
    fn new(bytes: &[u8]) -> Result<Self, AkitaError> {
        let mut words = match native_words(bytes)? {
            Cow::Owned(words) => words,
            Cow::Borrowed(words) => {
                let mut owned = Vec::new();
                owned
                    .try_reserve_exact(words.len())
                    .map_err(|_| AkitaError::InvalidProof)?;
                owned.extend_from_slice(words);
                owned
            }
        };
        for word in &mut words {
            *word = u64::from_le(*word);
        }
        Ok(Self { words, used: 0 })
    }
    fn take(&mut self, count: usize) -> Result<&[u64], AkitaError> {
        let begin = self.used;
        let end = begin.checked_add(count).ok_or(AkitaError::InvalidProof)?;
        let words = self.words.get(begin..end).ok_or(AkitaError::InvalidProof)?;
        self.used = end;
        Ok(words)
    }
    fn finished(&self) -> bool {
        self.used == self.words.len()
    }
}
struct Hints {
    quartets: Tape,
    positions: Option<Tape>,
}
thread_local! {
    static HINTS: RefCell<Option<Hints>> = const { RefCell::new(None) };
}

/// Install untrusted hints within a trusted verifier resource budget.
///
/// `max_bytes` bounds the entire input, including the versioned frame header.
/// Derive it from trusted schedule/configuration data or an application memory
/// budget, never from the untrusted advice's declared length. Every used quartet
/// or position rank is still authenticated against transcript bits.
///
/// Call [`finish_checked_hints`] after successful verification to require complete
/// consumption, or [`abort_checked_hints`] after a verification error. Both clear
/// the installed hints so the current thread can verify another proof.
///
/// # Errors
///
/// Returns [`AkitaError::InvalidProof`] if a session already exists, the input
/// exceeds `max_bytes`, the frame is malformed, or tape allocation fails. Session,
/// length and framing checks precede all tape allocation; failed installation
/// leaves the previous session unchanged.
pub fn install_checked_hints(bytes: &[u8], max_bytes: usize) -> Result<(), AkitaError> {
    HINTS.with(|state| {
        let mut state = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?;
        if state.is_some() || bytes.is_empty() || bytes.len() > max_bytes {
            return Err(AkitaError::InvalidProof);
        }
        let (quartets, positions) = if let Some(rest) = bytes.strip_prefix(b"AKITAH02") {
            let size = rest
                .get(..8)
                .and_then(|b| b.try_into().ok())
                .map(u64::from_le_bytes)
                .and_then(|n| usize::try_from(n).ok())
                .ok_or(AkitaError::InvalidProof)?;
            let rest = rest.get(8..).ok_or(AkitaError::InvalidProof)?;
            let (quartets, positions) = rest
                .split_at_checked(size)
                .ok_or(AkitaError::InvalidProof)?;
            (quartets, Some(positions))
        } else {
            (bytes, None)
        };
        if !quartets.len().is_multiple_of(8)
            || positions.is_some_and(|p| !p.len().is_multiple_of(8))
        {
            return Err(AkitaError::InvalidProof);
        }
        *state = Some(Hints {
            quartets: Tape::new(quartets)?,
            positions: positions.map(Tape::new).transpose()?,
        });
        Ok(())
    })
}
/// Remove installed hints and reject unless every hint was consumed.
/// An incomplete session is cleared even when this returns an error.
pub fn finish_checked_hints() -> Result<(), AkitaError> {
    HINTS.with(|state| {
        let hints = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?
            .take();
        match hints {
            Some(h) if h.quartets.finished() && h.positions.as_ref().is_none_or(Tape::finished) => {
                Ok(())
            }
            _ => Err(AkitaError::InvalidProof),
        }
    })
}
/// Discard hints after a failed verification. This does not authenticate the
/// hints or make the failed proof valid; it only releases the thread's session.
pub fn abort_checked_hints() -> Result<(), AkitaError> {
    HINTS.with(|state| {
        state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?
            .take();
        Ok(())
    })
}

pub(crate) fn active() -> bool {
    HINTS.with(|s| s.borrow().is_some())
}
pub(crate) fn positions_active() -> bool {
    HINTS.with(|s| s.borrow().as_ref().is_some_and(|h| h.positions.is_some()))
}

/// Consume a bounded slice without allocating another owner or copying words.
/// The decoder cannot retain a borrow after the thread-local session is released.
pub(crate) fn take<T>(
    kind: HintTape,
    count: usize,
    decode: impl FnOnce(&[u64]) -> Result<T, AkitaError>,
) -> Result<T, AkitaError> {
    HINTS.with(|state| {
        let mut state = state
            .try_borrow_mut()
            .map_err(|_| AkitaError::InvalidProof)?;
        let hints = state.as_mut().ok_or(AkitaError::InvalidProof)?;
        let (tape, words) = match kind {
            HintTape::Quartets => (
                &mut hints.quartets,
                count.checked_mul(4).ok_or(AkitaError::InvalidProof)?,
            ),
            HintTape::Positions => (
                hints.positions.as_mut().ok_or(AkitaError::InvalidProof)?,
                count,
            ),
        };
        decode(tape.take(words)?)
    })
}

/// Borrow whole native-endian words when aligned, copying only unaligned input.
/// Callers convert each word from little endian before interpreting it.
pub(crate) fn native_words(bytes: &[u8]) -> Result<Cow<'_, [u64]>, AkitaError> {
    if !bytes.len().is_multiple_of(8) {
        return Err(AkitaError::InvalidProof);
    }
    // SAFETY: u64 admits every initialized bit pattern. align_to supplies only
    // aligned words within the input, whose lifetime is retained by the borrow.
    let (prefix, words, suffix) = unsafe { bytes.align_to::<u64>() };
    if prefix.is_empty() && suffix.is_empty() {
        return Ok(Cow::Borrowed(words));
    }
    let mut words = Vec::new();
    words
        .try_reserve_exact(bytes.len() / 8)
        .map_err(|_| AkitaError::InvalidProof)?;
    words.extend(
        bytes
            .chunks_exact(8)
            .map(|c| u64::from_ne_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]])),
    );
    Ok(Cow::Owned(words))
}

#[inline(always)]
pub(crate) fn validate(
    words: &[u64; 4],
    expected_rank: u128,
    pm1_rank_space: u128,
    signs: u64,
) -> Result<(), AkitaError> {
    let (mut n1, mut n2, mut r1, mut r2, mut s1, mut s2) = (0usize, 0usize, 0u64, 0u64, 0u64, 0u64);
    // Every admitted code is four coefficients in {-2,-1,0,1,2}. Before quartet q,
    // each prefix count and the complement prefix lie in 0..=4*q, hence 0..=60.
    // The rank table covers that whole range, including hints with wrong final counts.
    macro_rules! step {
        ($q:literal,$word:expr,$shift:literal) => {{
            let code = (($word >> $shift) & 1023) as usize;
            let meta = *META.get(code).ok_or(AkitaError::InvalidProof)?;
            let m1 = ((meta >> 6) & 15) as usize;
            let m2 = ((meta >> 10) & 15) as usize;
            if m2 != 0 {
                r2 += RANK_CONTRIBUTIONS[(($q * 4 - n1) * 61 + n2) * 16 + m2];
                s2 |= ((meta >> 18) & 15) << n2;
                n2 += ((meta >> 3) & 7) as usize;
            }
            if m1 != 0 {
                r1 += RANK_CONTRIBUTIONS[(($q * 4) * 61 + n1) * 16 + m1];
                s1 |= ((meta >> 14) & 15) << n1;
                n1 += (meta & 7) as usize;
            }
        }};
    }
    step!(0, words[0], 0);
    step!(1, words[0], 10);
    step!(2, words[0], 20);
    step!(3, words[0], 30);
    step!(4, words[1], 0);
    step!(5, words[1], 10);
    step!(6, words[1], 20);
    step!(7, words[1], 30);
    step!(8, words[2], 0);
    step!(9, words[2], 10);
    step!(10, words[2], 20);
    step!(11, words[2], 30);
    step!(12, words[3], 0);
    step!(13, words[3], 10);
    step!(14, words[3], 20);
    step!(15, words[3], 30);

    if n1 != 31
        || n2 != 10
        || (r1 as u128) + pm1_rank_space * (r2 as u128) != expected_rank
        || (s1 | (s2 << 31)) != signs
    {
        return Err(AkitaError::InvalidProof);
    }
    Ok(())
}
